params.spec:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Where the current selection connected from, in the time picker's range. Points are resolved client locations sized by event volume; a line joins one location to the next the same identity appeared from, colored by the speed that move implies between last seen there and first seen here. Places are aggregated per city, so an identity active in two cities at overlapping times is marked as such rather than given an impossible speed. Read the title line first: many events cannot be placed at all — an address geoip never placed (always the case for CGNAT and private addresses), an event with no client IP, or an event from a placeable address that predates geo enrichment — so the absence of a line is not evidence of absence. An address counts as unplaceable only when none of its events were placed, as in \"Busiest addresses they used\". The line legend appears only when there is a line to read. This is a movement record, not an impossible-travel detector.",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "config": {
    "view": {
      "stroke": null
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 11
    },
    "title": {
      "fontSize": 12,
      "fontWeight": 500,
      "anchor": "start",
      "subtitleFontSize": 11
    }
  },
  "title": {
    "text": {
      "expr": "length(data('coverage')) && data('coverage')[0].total > 0 ? ['On the map: ' + data('coverage')[0].on_map + '% of events · address cannot be placed: ' + data('coverage')[0].cannot + '%', 'no client IP: ' + data('coverage')[0].no_client_ip + '%' + (data('coverage')[0].before_enrichment !== '0' ? ' · before geo enrichment: ' + data('coverage')[0].before_enrichment + '%' : '')] : 'No activity for this selection in this time range'"
    },
    "subtitle": {
      "expr": "!length(data('places')) ? '' : extent(pluck(data('places'), 'places'))[1] > 1 ? 'Lines join consecutive locations for one identity; color is the travel speed that would imply.' : 'Each identity was seen from one place in this range, so there is no travel to draw.'"
    }
  },
  "projection": {
    "type": "naturalEarth1"
  },
  "data": {
    "name": "places",
    "url": {
      "%type%": "esql",
      "query": "SET unmapped_fields=\"nullify\"; FROM logs-elastic_cloud.serverless_audit.otel-* | WHERE @timestamp <= ?_tend AND @timestamp > ?_tstart | WHERE client.geo.location IS NOT NULL | EVAL actor = COALESCE(user.email, api_key.id, user.name, TO_STRING(client.ip)) | STATS events = COUNT(*), at = ST_CENTROID_AGG(client.geo.location), first_seen = MIN(@timestamp), last_seen = MAX(@timestamp) BY actor, city = client.geo.city_name, country = client.geo.country_name | INLINE STATS places = COUNT(*) BY actor | EVAL lon = ST_X(at), lat = ST_Y(at), first_ms = TO_LONG(first_seen), last_ms = TO_LONG(last_seen) | KEEP actor, city, country, places, lon, lat, events, first_seen, last_seen, first_ms, last_ms | SORT events DESC | LIMIT 150",
      "%timefield%": "@timestamp",
      "%context%": true
    }
  },
  "layer": [
    {
      "data": {
        "name": "world",
        "url": {
          "%type%": "emsfile",
          "name": "World Countries"
        },
        "format": {
          "type": "topojson",
          "feature": "data"
        }
      },
      "transform": [
        {
          "filter": "datum.properties.iso2 !== 'AQ'"
        }
      ],
      "mark": {
        "type": "geoshape",
        "fill": "#98A2B3",
        "fillOpacity": 0.35,
        "stroke": "#98A2B3",
        "strokeWidth": 0.5,
        "strokeOpacity": 0.9
      }
    },
    {
      "data": {
        "name": "coverage",
        "url": {
          "%type%": "esql",
          "query": "FROM logs-elastic_cloud.serverless_audit.otel-* | WHERE @timestamp <= ?_tend AND @timestamp > ?_tstart | STATS n = COUNT(*), located = COUNT(client.geo.location), placed = COUNT(client.geo.country_iso_code) BY client.ip | STATS total = SUM(n), located = SUM(located), with_ip = SUM(CASE(client.ip IS NOT NULL, n, 0)), unplaceable = SUM(CASE(client.ip IS NOT NULL AND placed == 0, n, 0)) | EVAL no_ip = total - with_ip, older = with_ip - unplaceable - located | EVAL r_map = TO_LONG(ROUND(100.0 * located / total)), r_noip = TO_LONG(ROUND(100.0 * no_ip / total)), r_older = TO_LONG(ROUND(100.0 * older / total)) | EVAL r_cannot = 100 - r_map - r_noip - r_older | EVAL on_map = CASE(located == 0, \"0\", r_map < 1, \"<1\", TO_STRING(r_map)), no_client_ip = CASE(no_ip == 0, \"0\", r_noip < 1, \"<1\", TO_STRING(r_noip)), before_enrichment = CASE(older == 0, \"0\", r_older < 1, \"<1\", TO_STRING(r_older)), cannot = CASE(unplaceable == 0, \"0\", r_cannot < 1, \"<1\", TO_STRING(r_cannot)) | KEEP total, on_map, cannot, no_client_ip, before_enrichment",
          "%timefield%": "@timestamp",
          "%context%": true
        }
      },
      "mark": {
        "type": "point",
        "opacity": 0
      },
      "encoding": {
        "longitude": {
          "datum": 0
        },
        "latitude": {
          "datum": 0
        }
      }
    },
    {
      "transform": [
        {
          "calculate": "datum.actor || '(no email recorded)'",
          "as": "who"
        },
        {
          "window": [
            {
              "op": "lag",
              "field": "lon",
              "as": "p_lon"
            },
            {
              "op": "lag",
              "field": "lat",
              "as": "p_lat"
            },
            {
              "op": "lag",
              "field": "last_ms",
              "as": "p_last"
            },
            {
              "op": "lag",
              "field": "city",
              "as": "p_city"
            }
          ],
          "groupby": [
            "who"
          ],
          "sort": [
            {
              "field": "first_ms",
              "order": "ascending"
            }
          ]
        },
        {
          "filter": "datum.p_lon != null && (datum.lon !== datum.p_lon || datum.lat !== datum.p_lat)"
        },
        {
          "calculate": "6371 * acos(min(1, sin(datum.p_lat * PI / 180) * sin(datum.lat * PI / 180) + cos(datum.p_lat * PI / 180) * cos(datum.lat * PI / 180) * cos((datum.lon - datum.p_lon) * PI / 180)))",
          "as": "km"
        },
        {
          "calculate": "(datum.first_ms - datum.p_last) / 3600000",
          "as": "hours"
        },
        {
          "calculate": "datum.hours <= 0 ? 'seen in both at overlapping times' : datum.km / datum.hours > 900 ? 'faster than flying (>900 km/h)' : datum.km / datum.hours > 300 ? 'faster than driving (>300 km/h)' : 'plausible travel'",
          "as": "reading"
        }
      ],
      "mark": {
        "type": "rule",
        "strokeWidth": 1.8,
        "opacity": 0.85
      },
      "encoding": {
        "longitude": {
          "field": "p_lon",
          "type": "quantitative"
        },
        "latitude": {
          "field": "p_lat",
          "type": "quantitative"
        },
        "longitude2": {
          "field": "lon"
        },
        "latitude2": {
          "field": "lat"
        },
        "color": {
          "field": "reading",
          "type": "nominal",
          "scale": {
            "domain": [
              "plausible travel",
              "faster than driving (>300 km/h)",
              "faster than flying (>900 km/h)",
              "seen in both at overlapping times"
            ],
            "range": [
              "#199e70",
              "#c98500",
              "#d95926",
              "#9085e9"
            ]
          },
          "legend": {
            "title": null,
            "orient": "bottom",
            "direction": "horizontal",
            "symbolType": "stroke",
            "labelLimit": 220,
            "labelOpacity": {
              "expr": "extent(pluck(data('places'), 'places'))[1] > 1 ? 1 : 0"
            },
            "symbolOpacity": {
              "expr": "extent(pluck(data('places'), 'places'))[1] > 1 ? 1 : 0"
            }
          }
        },
        "tooltip": [
          {
            "field": "who",
            "title": "Identity"
          },
          {
            "field": "p_city",
            "title": "From"
          },
          {
            "field": "city",
            "title": "To"
          },
          {
            "field": "km",
            "title": "Distance (km)",
            "format": ",.0f"
          },
          {
            "field": "hours",
            "title": "Gap (hours)",
            "format": ",.1f"
          },
          {
            "field": "reading",
            "title": "Reading"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "calculate": "datum.actor || '(no email recorded)'",
          "as": "who"
        }
      ],
      "mark": {
        "type": "circle",
        "color": "#3987e5",
        "opacity": 0.8
      },
      "encoding": {
        "longitude": {
          "field": "lon",
          "type": "quantitative"
        },
        "latitude": {
          "field": "lat",
          "type": "quantitative"
        },
        "size": {
          "field": "events",
          "type": "quantitative",
          "scale": {
            "type": "sqrt",
            "range": [
              25,
              700
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "who",
            "title": "Identity"
          },
          {
            "field": "city",
            "title": "City"
          },
          {
            "field": "country",
            "title": "Country"
          },
          {
            "field": "events",
            "title": "Events",
            "format": ","
          },
          {
            "field": "first_seen",
            "title": "First seen",
            "type": "temporal",
            "format": "%d %b %H:%M"
          },
          {
            "field": "last_seen",
            "title": "Last seen",
            "type": "temporal",
            "format": "%d %b %H:%M"
          }
        ]
      }
    }
  ]
}
